sysevent_in_email_action.script:
(function runAction(current, event, email, logger) {

    var STATE_PENDING = '-5';
    var STATE_IN_PROGRESS = '2';
    var TABLE = 'x_fub_fundbrad_ev_atendimento_ev';

    if (!current.isValidRecord() ||
        current.getRecordClassName() !== TABLE ||
        current.getValue('u_origem') !== 'escola_virtual' ||
        current.getValue('state') !== STATE_PENDING) {
        return;
    }

    var headers = String(email.headers || '');
    var fromMatch = headers.match(/^From:\s*(.+)$/im);

    var sender = String(
        email.origemail ||
        email.from ||
        (fromMatch ? fromMatch[1] : '')
    ).trim().toLowerCase();

    var requester = String(
        current.getValue('u_email_solicitante') || ''
    ).trim().toLowerCase();

    // Utiliza email.body_text direto(com fallback para o body limpo caso venha vazio)
    var rawBody = String(email.body_text || email.body || '').trim();

    // ==========================================
    // TRATAMENTO DO CORPO DO E-MAIL(Limpeza HTML e Histórico)
    // ==========================================

    // 1. Corta o texto antes da linha do cabeçalho de resposta do Outlook / e-mail
    var userResponse = rawBody.split(/De:\s*IT Service Desk|From:|-----Original Message-----/i)[0].trim();

    // 2. Remove eventuais tags HTML remanescentes, blocos de estilo e normaliza espaços
    var cleanText = userResponse
        .replace(/<head[\s\S]*?<\/head>/gi, '')   // Remove a tag <head>
        .replace(/<style[\s\S]*?<\/style>/gi, '') // Remove CSS
        .replace(/&lt;script&gt;/gi, '')// Remove scripts
        .replace(/<br\s*\/?>/gi, '\n')             // Converte tags <br> em quebras de linha reais
        .replace(/<\/p>/gi, '\n\n')                 // Converte fim de parágrafos em quebra dupla
        .replace(/<[^>]+>/g, '')                   // Remove demais tags HTML sem trocar por espaço
        .replace(/&nbsp;/gi, ' ')                  // Converte espaços HTML
        .replace(/&lt;/gi, '<')
        .replace(/&gt;/gi, '>')
        .replace(/[ \t]+/g, ' ')                   // Normaliza apenas espaços horizontais(MANTÉM \n)
        .replace(/\n\s*\n\s*\n+/g, '\n\n')         // Limita múltiplos saltos de linha no máximo a 2
        .trim();

    current.comments = 'Resposta do aluno:\n\n' + cleanText;
    current.setValue('state', STATE_IN_PROGRESS);
    current.setValue('substate', '');

    var updatedSysId = current.update();

    if (!updatedSysId) {
        logger.log('EV: Falha ao atualizar atendimento.');
    } else {
        logger.log('EV: Atendimento atualizado com sucesso.');

        gs.info('EV: Anexo de assinatura/rodapé removido via GlideRecord: 0');
        // ==========================================   
        // REMOÇÃO DE ANEXOS INDESEJADOS DO HEADER/FOOTER
        // ==========================================
        gs.info('EV: Anexo de assinatura/rodapé removido via GlideRecord: 1');

        gs.eventQueue(
            'ev.email.cleanup_images',
            current,
            '',
            ''
        );

    }

})(current, event, email, logger);
